#!/usr/bin/env python3
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-04
"""Self-contained HTML view of an extract_fish_tasks.py JSON: the task set, the DAG of each multi-callback task
(layered left to right, hover for labels, click a callback to isolate its chain), the response time of every callback
relative to a source (the chains), the sampled dependencies to other tasks, and the single-callback tasks.

  python3 task_viz.py <fish_tasks.json> -o tasks.html [--standalone]

Without --standalone the output is a page fragment (no doctype/html/body) as the artifact publisher expects;
with it, a complete HTML document for opening as a local file. Layout is computed here (longest-path layers,
barycenter ordering), the page only draws."""
import argparse, collections, json, os

NW, NH, GX, GY, PAD = 204, 40, 64, 12, 16


def short_node(name, n=24):
    parts = [p for p in name.strip().split('/') if p]
    s = '/'.join(parts[-2:]) if len(parts) > 1 else (parts[0] if parts else name)
    return s if len(s) <= n else s[:n - 1] + '…'


def short_ent(etype, ent, T_cfg=None, n=17):
    if etype == 'tmr':
        return 'timer ' + (f"{T_cfg / 1e6:g} ms" if T_cfg else '')
    tail = [p for p in str(ent).split('/') if p]
    s = {'sub': 'sub ', 'serv': 'srv ', 'cli': 'cli '}.get(etype, str(etype) + ' ') + (tail[-1] if tail else '')
    return s if len(s) <= n else s[:n - 1] + '…'


def layout(nodes, edges):
    ids = [n['id'] for n in nodes]; succ = collections.defaultdict(list); indeg = collections.Counter()
    state = {}; dag = []
    adj = collections.defaultdict(list)
    for e in edges:
        if e['u'] != e['v']:
            adj[e['u']].append(e['v'])
    def dfs(u):                      # drop back edges so that layering terminates on cyclic tasks
        state[u] = 1
        for v in adj[u]:
            if state.get(v) == 1:
                continue
            dag.append((u, v))
            if v not in state:
                dfs(v)
        state[u] = 2
    import sys; sys.setrecursionlimit(10000)
    for u in ids:
        if u not in state:
            dfs(u)
    for u, v in dag:
        succ[u].append(v); indeg[v] += 1
    layer = {u: 0 for u in ids}; q = [u for u in ids if indeg[u] == 0]; pred = collections.defaultdict(list)
    while q:
        u = q.pop()
        for v in succ[u]:
            layer[v] = max(layer[v], layer[u] + 1); pred[v].append(u); indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)
    L = collections.defaultdict(list)
    for u in sorted(ids, key=str):
        L[layer[u]].append(u)
    pos = {}
    for l in L:
        for i, u in enumerate(L[l]):
            pos[u] = i
    for _ in range(6):               # barycenter sweeps, forward then backward
        for l in sorted(L)[1:]:
            L[l].sort(key=lambda u: (sum(pos[p] for p in pred[u]) / len(pred[u])) if pred[u] else pos[u])
            for i, u in enumerate(L[l]): pos[u] = i
        for l in sorted(L, reverse=True)[1:]:
            L[l].sort(key=lambda u: (sum(pos[s] for s in succ[u]) / len(succ[u])) if succ[u] else pos[u])
            for i, u in enumerate(L[l]): pos[u] = i
    tall = max(len(v) for v in L.values())
    xy = {}
    for l in L:
        off = (tall - len(L[l])) * (NH + GY) / 2
        for i, u in enumerate(L[l]):
            xy[u] = (PAD + l * (NW + GX), PAD + off + i * (NH + GY))
    return xy, PAD * 2 + (max(L) + 1) * (NW + GX) - GX, PAD * 2 + tall * (NH + GY) - GY


def main():
    ap = argparse.ArgumentParser(); ap.add_argument('json'); ap.add_argument('-o', '--out', required=True)
    ap.add_argument('--standalone', action='store_true')
    a = ap.parse_args()
    d = json.load(open(a.json))
    data = [t for t in d['tasks'] if not t['infra']]
    V = {v['id']: (v, t['id']) for t in d['tasks'] for v in t['vertices']}
    tname = {}
    out_tasks = []
    for t in data:
        v0 = t['vertices'][0]
        src0 = t['sources'][0] if t['sources'] else None
        nm = src0['name'] if src0 else v0['name']
        nm = nm.split('→')[-1].strip() if '→' in nm else nm
        if len(t['sources']) > 1:
            nm += f" + {len(t['sources']) - 1} more"
        tname[t['id']] = nm
    dup = collections.Counter(tname.values())
    for t in data:          # two tasks fed by the same bag topic: tell them apart by their first callback
        if dup[tname[t['id']]] > 1:
            tname[t['id']] += ' → ' + short_node(t['vertices'][0]['node'], 40)
    for t in [t for t in data if t['size'] > 1]:
        vids = {v['id'] for v in t['vertices']}
        nodes = []; edges = []
        for v in t['vertices']:
            r = v.get('resource') or {}
            T_cfg = (v.get('arrival') or {}).get('T_cfg')
            kind = 'gpu' if v.get('gpu') else 'mt' if r.get('mode') == 'MT' else 'st'
            jn = v.get('join') or {}
            nodes.append(dict(id=v['id'], k=kind, a=short_node(v['node']), b=short_ent(v['etype'], v['entity'], T_cfg),
                              name=v['name'], n=v['n'], C=v.get('C'), S=v.get('S_total'), Sg=v.get('S_gpu'), B=v.get('B_lock'),
                              I=v.get('I_obs'), ex=r.get('executor'), mode=r.get('mode'), thr=r.get('ran_on_threads'),
                              cbg=r.get('cb_group_type'), act=v.get('activation'), join=jn.get('role'), roles=jn.get('roles'),
                              exact=jn.get('exact'), seg=(v.get('segments') or {}).get('pattern'), segshare=(v.get('segments') or {}).get('share'),
                              T=T_cfg, clock=(v.get('arrival') or {}).get('clock'), helpers=(v.get('helpers') or {}).get('p50')))
        for e in t['edges']:
            if not (e.get('n_pairs') or e['kind'] == 'join'):
                continue
            u = e['u']
            if u not in vids:            # stimulus: a publisher thread outside the task — one source node per topic
                u = f"s{e['u']}:{e['topic']}"
                if not any(n['id'] == u for n in nodes):
                    nodes.append(dict(id=u, k='src', a=short_node(str(e['topic']), 24), b='bag stimulus', name=f"stimulus {e['topic']}", n=None))
            if e['v'] not in vids:
                continue
            q = lambda x, k: (x or {}).get(k)
            edges.append(dict(u=u, v=e['v'], kind=e['kind'], topic=e['topic'], n=e.get('n_pairs') or 0, d50=q(e.get('delta'), 'p50'),
                              dmax=q(e.get('delta'), 'max'), q50=q(e.get('dispatch'), 'p50'), qmax=q(e.get('dispatch'), 'max'),
                              size=q(e.get('size'), 'p50'), wr=q(e.get('write'), 'p50'), prov=e.get('prov')))
        xy, w, h = layout(nodes, edges)
        for n in nodes:
            n['x'], n['y'] = xy[n['id']]
        srcs = []
        for s in t['sources']:
            rows = [dict(v=int(f), ratio=r['ratio'], p50=r['R']['p50'], p99=r['R']['p99'], max=r['R']['max'])
                    for f, r in (s.get('reach') or {}).items() if r.get('R') and int(f) in vids]
            rows.sort(key=lambda r: r['p50'])
            nm = s['name'].split('→')[-1].strip() if '→' in s['name'] else s['name']
            srcs.append(dict(name=nm, kind=s['kind'], n=s['n_releases'], T=s.get('T_cfg'), ia=s.get('inter_arrival'), R=s.get('job_R'),
                             shapes=s.get('n_shapes'), rows=rows))
        deps = collections.defaultdict(lambda: dict(n=0, ages=[], methods=collections.Counter(), topics=set()))
        for sp in d['sampled']:
            rt = sp.get('reader_task'); wts = [w_ for w_ in sp.get('writer_tasks') or [] if w_ is not None]
            for wt in wts:
                if rt == t['id'] and wt != rt:
                    k = ('reads from', wt)
                elif wt == t['id'] and rt is not None and rt != wt:
                    k = ('read by', rt)
                else:
                    continue
                dd = deps[k]; dd['n'] += 1; dd['methods'][sp.get('method') or 'state'] += 1; dd['topics'].add(sp.get('topic'))
                if sp.get('age_p50') and sp.get('method') != 'tf_static':
                    dd['ages'].append(sp['age_p50'])
        deplist = [dict(dir=k[0], task=tname.get(k[1], str(k[1])), size=next((x['size'] for x in data if x['id'] == k[1]), 1),
                        n=v['n'], method=', '.join(f"{m} {c}" for m, c in v['methods'].most_common()),
                        age=sorted(v['ages'])[len(v['ages']) // 2] if v['ages'] else None,
                        topics=sorted(x for x in v['topics'] if x)[:4]) for k, v in deps.items()]
        deplist.sort(key=lambda x: (x['dir'], -x['n']))
        out_tasks.append(dict(id=t['id'], name=tname[t['id']], size=t['size'], nsrc=len(t['sources']), nex=len(t['executors']),
                              strict=t.get('strict_edd'), nodes=nodes, edges=edges, w=w, h=h, sources=srcs, deps=deplist))
    singles = []
    for t in [t for t in data if t['size'] == 1]:
        v = t['vertices'][0]; ar = v.get('arrival') or {}
        s0 = t['sources'][0] if t['sources'] else {}
        singles.append(dict(name=v['name'], kind=v['etype'], T=ar.get('T_cfg'), gap=(ar.get('gap') or s0.get('inter_arrival') or {}).get('p50'),
                            C=(v.get('C') or {}).get('p50'), clock=ar.get('clock'), mode=(v.get('resource') or {}).get('mode'), n=v['n']))
    singles.sort(key=lambda s: -(s['C'] or 0) * (s['n'] or 0))
    W = d['window']
    payload = dict(session=d['session'], window_s=round((W['t_end'] - W['t_ss']) / 1e9, 1),
                   stats=dict(tasks=len(data), multi=len(out_tasks), single=len(singles),
                              callbacks=sum(len(t['vertices']) for t in data),
                              edges=sum(1 for t in data for e in t['edges'] if e.get('n_pairs')), sampled=len(d['sampled'])),
                   tasks=out_tasks, singles=singles, geom=dict(NW=NW, NH=NH))
    html = TEMPLATE.replace('__DATA__', json.dumps(payload, separators=(',', ':')).replace('</', '<\\/'))
    if a.standalone:
        html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"></head><body>' + html + '</body></html>'
    open(a.out, 'w').write(html)
    print(f"{a.out}: {len(out_tasks)} multi-callback tasks, {len(singles)} single-callback tasks, {os.path.getsize(a.out) / 1024:.0f} kB")


